  extractedIssues: Array<{
    id: string;
    title: string;
    description: string;
    category: string;
  }>;
  priorityAssignments: Array<{
    issueId: string;
    priority: "critical" | "high" | "medium" | "low";
    reasoning: string;
  }>;
